这是我的登录代码，你看和上面的问题是不是有关：
<!-- src/views/login/LoginPage.vue -->
<template>
  <div class="login-container">
    <div class="login-wrapper">
      <div class="logo-title-container">
        <img :src="logo" alt="团团赚拼购" class="logo" />
        <h1 class="system-title">团团赚拼购</h1>
      </div>

      <El-form
        ref="loginFormRef"
        :model="loginForm"
        :rules="loginRules"
        class="login-form"
      >
        <El-form-item prop="username">
          <El-input
            v-model="loginForm.username"
            prefix-icon="User"
            placeholder="用户名"
            clearable
          />
        </El-form-item>

        <El-form-item prop="password">
          <El-input
            v-model="loginForm.password"
            type="password"
            prefix-icon="Lock"
            placeholder="密码"
            show-password
          />
        </El-form-item>

        <El-form-item>
          <El-button
            type="primary"
            class="login-btn"
            :loading="isLoading"
            :disabled="isLoading"
            @click="handleLogin"
          >
            登录
          </El-button>
        </El-form-item>

        <div class="login-extra">
          <El-link type="primary" @click="handleRegister">立即注册</El-link>
          <El-link type="info" @click="handleForgotPassword">忘记密码</El-link>
        </div>
      </El-form>
    </div>
  </div>
</template>

<script setup>
import { reactive, ref } from "vue";
import { useRouter } from "vue-router";
import { ElMessage } from "element-plus";
import logo from "@/assets/logo.png";
import { useStore } from "vuex"; // 引入 Vuex

const loginFormRef = ref(null);
const router = useRouter();
const store = useStore(); // 获取 Vuex store

// 登录表单数据
const loginForm = reactive({
  username: "",
  password: "",
});

// 表单验证规则
const loginRules = {
  username: [
    {
      required: true,
      message: "请输入用户名",
      trigger: "blur",
    },
  ],
  password: [
    {
      required: true,
      message: "请输入密码",
      trigger: "blur",
    },
    {
      min: 6,
      message: "密码不能少于6位",
      trigger: "blur",
    },
  ],
};

// 加载状态
const isLoading = ref(false);

const handleLogin = async () => {
  // 先验证表单
  try {
    const valid = await loginFormRef.value.validate(); // 验证表单
    if (!valid) {
      ElMessage.error("请检查输入，确保用户名和密码都已填写。");
      return; // 如果不合法，返回，不继续执行后面的代码
    }

    isLoading.value = true; // 启动加载状态

    // 调用 Vuex 的 login action
    const response = await store.dispatch("login", {
      username: loginForm.username,
      password: loginForm.password,
    });
    const user = response.data; // 假设返回用户的完整信息对象
    store.commit("setUser", user); // 传入完整的用户对象
    localStorage.setItem("user", JSON.stringify(user)); // 同时存储到 localStorage

    // 检查响应是否包含用户信息
    if (response && response.user) {

      console.log("登录成功的用户信息:", response.user); // 打印查看用户信息结构
      ElMessage.success("登录成功");
      await router.push({ name: "Home" }); // 跳转到主页
    } else {
      ElMessage.error("用户名或密码错误"); // 处理不正确的用户信息
    }
  } catch (error) {
    ElMessage.error("登录失败，请重试。"); // 捕获错误并提示
  } finally {
    isLoading.value = false; // 重置加载状态
  }
};

// 注册处理
const handleRegister = () => {
  router.push({ name: "Register" }); // 跳转到注册页面
};

// 找回密码处理
const handleForgotPassword = () => {
  router.push({ name: "ForgetPassword" }); // 跳转到找回密码界面
};
</script>

<style scoped>
.login-container {
  display: flex;
  justify-content: center;
  align-items: center;
  height: 100vh;
  background: linear-gradient(to right, #3494e6, #ec6ead);
}

.login-wrapper {
  width: 400px;
  padding: 30px;
  background: white;
  border-radius: 10px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.1);
  text-align: center;
}

.logo-title-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  margin-bottom: 20px;
}

.logo {
  width: 140px;
  height: 80px;
  margin-bottom: 10px;
}

.system-title {
  font-size: 24px;
  color: #333;
  font-weight: bold;
}

.login-form {
  width: 100%;
}

.login-btn {
  width: 100%;
  margin-top: 10px;
}

.login-extra {
  display: flex;
  justify-content: space-between;
  margin-top: 10px;
}
</style>
